<template>
  <div class="product-card" :class="{ 'out-of-stock': product.is_oos }">
    <div class="card-image">
      <img v-if="product.image_url" :src="product.image_url" :alt="product.name" />
      <div v-else class="image-placeholder">📦</div>
    </div>

    <div class="card-content">
      <h3 class="product-name">{{ product.name }}</h3>
      <div class="product-meta">
        <div class="sku">{{ product.sku }}</div>
        <div class="weight" v-if="product.weight">{{ product.weight }}</div>
      </div>

      <div class="price-row">
        <div class="price">{{ formatPrice(product.price) }}</div>
        <button
          class="btn-favorite"
          :class="{ active: isFavorite }"
          @click="toggleFavorite"
          title="Toggle favorite"
        >
          ❤️
        </button>
      </div>

      <div class="stock-status">
        <span v-if="!product.is_oos" class="in-stock">In Stock</span>
        <span v-else class="out-of-stock-badge">Out of Stock</span>
      </div>

      <button
        class="btn-add-cart"
        :disabled="product.is_oos"
        @click="addToCart"
      >
        + Add to Cart
      </button>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'

const props = defineProps({
  product: {
    type: Object,
    required: true
  },
  favorites: {
    type: Array,
    default: () => []
  }
})

const emit = defineEmits(['add-to-cart', 'toggle-favorite'])

const isFavorite = computed(() => {
  return props.favorites.includes(props.product.id)
})

const formatPrice = (price) => {
  if (!price) return 'Contact for price'
  return `$${parseFloat(price).toFixed(2)}`
}

const addToCart = () => {
  emit('add-to-cart', {
    product_id: props.product.id,
    quantity: 1
  })
}

const toggleFavorite = () => {
  emit('toggle-favorite', props.product.id)
}
</script>

