            <div>No favorites yet. Add items from the catalog.</div>
          </div>
          <div v-else class="product-grid" :style="{ '--card-scale': cardScale }">
            <ProductCard
              v-for="product in favoriteProducts"
              :key="product.id"
              :product="product"
              :favorites="favorites"
              @add-to-cart="addToCart"
              @toggle-favorite="toggleFavorite"
            />
          </div>
        </div>

        <!-- Orders Tab -->
        <div v-show="currentTab === 'orders'" class="tab-content">
          <div class="tab-header">
            <h2>Order History</h2>
          </div>
          <div v-if="orders.length === 0" class="empty-state">
            <div class="empty-icon">📦</div>
            <div>No orders yet.</div>
          </div>
          <div v-else class="orders-list">
            <div v-for="order in orders" :key="order.id" class="order-card">
              <div class="order-header">
                <div class="order-id">Order #{{ order.id }}</div>
                <div class="order-status" :class="order.status">{{ order.status }}</div>
              </div>
              <div class="order-detail">Date: {{ formatDate(order.created_at) }}</div>
              <div class="order-detail">Cases: {{ order.total_cases || 0 }}</div>
              <div class="order-detail">Total: {{ formatPrice(order.total_amount || 0) }}</div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Cart Drawer -->
    <CartDrawer
      :items="cartItems"
      :is-open="cartOpen"
      @close="cartOpen = false"
      @update-quantity="updateCartQuantity"
      @remove-item="removeFromCart"
      @clear-cart="cartItems = []"
      @checkout="handleCheckout"
    />

    <!-- Toast Notifications -->
    <div v-if="toast.show" class="toast" :class="toast.type">
