<script setup>
import { ref, computed, onMounted } from 'vue'
import axios from 'axios'
import Sidebar from './Sidebar.vue'
import ProductCard from './ProductCard.vue'
import CartDrawer from './CartDrawer.vue'

const props = defineProps({
  user: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['logout'])

// State
const products = ref([])
const categories = ref([])
const cartItems = ref([])
const favorites = ref([])
const orders = ref([])

// UI State
const currentTab = ref('products')
const sidebarOpen = ref(false)
const cartOpen = ref(false)
const accountOpen = ref(false)
const settingsOpen = ref(false)
const searchQuery = ref('')
const cardScale = ref(1)
const activeFilter = ref('all')

const toast = ref({ show: false, message: '', type: 'info' })

// Computed
const userInitial = computed(() => {
  return (props.user.company_name || 'U')[0].toUpperCase()
})

const filterTitle = computed(() => {
  if (activeFilter.value === 'all') return 'All Products'
  const cat = categories.value.find(c => c.id === activeFilter.value)
  return cat ? cat.name : 'Products'
})

const filteredProducts = computed(() => {
  let filtered = products.value

  // Apply category filter
  if (activeFilter.value !== 'all') {
    filtered = filtered.filter(p => p.category_id === activeFilter.value)
  }

  // Apply search
  if (searchQuery.value) {
    const q = searchQuery.value.toLowerCase()
    filtered = filtered.filter(p =>
      p.name.toLowerCase().includes(q) ||
      p.sku.toLowerCase().includes(q)
    )
  }

  return filtered
})

const favoriteProducts = computed(() => {
  return products.value.filter(p => favorites.value.includes(p.id))
})

// Methods
const fetchProducts = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/products`)
    const data = response.data.products || response.data
    products.value = Array.isArray(data) ? data : []
    
    // Extract unique categories from products
    const cats = {}
    products.value.forEach(p => {
      if (p.category_id && !cats[p.category_id]) {
        cats[p.category_id] = {
          id: p.category_id,
          name: p.category,
          emoji: '📁',
          count: 0
        }
      }
    })
    
    // Count products per category
    Object.keys(cats).forEach(catId => {
      cats[catId].count = products.value.filter(p => p.category_id === parseInt(catId)).length
    })
    
    categories.value = Object.values(cats)
  } catch (err) {
    showToast('Failed to load products', 'error')
  }
}

const fetchOrders = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/orders`)
    const data = response.data.orders || response.data || []
    orders.value = Array.isArray(data) ? data : []
  } catch (err) {
    showToast('Failed to load orders', 'error')
  }
}

const addToCart = async (item) => {
  try {
    const existing = cartItems.value.find(c => c.product_id === item.product_id)
    const product = products.value.find(p => p.id === item.product_id)

    if (existing) {
      existing.quantity += item.quantity
    } else {
      cartItems.value.push({
        ...item,
        name: product.name,
        price: product.price,
        image_url: product.image_url
      })
    }

    // Persist to localStorage
    localStorage.setItem('cartItems', JSON.stringify(cartItems.value))
    showToast('Added to cart', 'success')
  } catch (err) {
    showToast('Failed to add to cart', 'error')
  }
}

const updateCartQuantity = (data) => {
  const item = cartItems.value.find(c => c.product_id === data.productId)
  if (item) {
    item.quantity = data.quantity
    localStorage.setItem('cartItems', JSON.stringify(cartItems.value))
  }
}

const removeFromCart = (productId) => {
  cartItems.value = cartItems.value.filter(c => c.product_id !== productId)
  localStorage.setItem('cartItems', JSON.stringify(cartItems.value))
}

const toggleFavorite = async (productId) => {
  const idx = favorites.value.indexOf(productId)
  try {
    if (idx >= 0) {
      // Remove favorite
      await axios.delete(`${import.meta.env.VITE_API_URL}/api/favorites/${productId}`)
      favorites.value.splice(idx, 1)
      showToast('Removed from favorites', 'success')
    } else {
      // Add favorite
      await axios.post(`${import.meta.env.VITE_API_URL}/api/favorites`, {
        product_id: productId
      })
      favorites.value.push(productId)
      showToast('Added to favorites', 'success')
    }
    localStorage.setItem('favorites', JSON.stringify(favorites.value))
  } catch (err) {
    showToast('Failed to update favorites', 'error')
  }
}

const toggleSidebar = () => {
  sidebarOpen.value = !sidebarOpen.value
}

const closeSidebar = () => {
  sidebarOpen.value = false
}

const toggleCart = () => {
  cartOpen.value = !cartOpen.value
  sidebarOpen.value = false
}

const handleFilterChange = (data) => {
  if (data.type === 'all') {
    activeFilter.value = 'all'
  } else if (data.type === 'category') {
    activeFilter.value = data.value
  } else if (data.type === 'special') {
    if (data.value === 'favorites') {
      currentTab.value = 'favorites'
      activeFilter.value = 'all'
    }
  }
  closeSidebar()
}

const handleCheckout = async () => {
  if (cartItems.value.length === 0) return

  try {
    const response = await axios.post(`${import.meta.env.VITE_API_URL}/api/orders`, {
      items: cartItems.value.map(item => ({
        product_id: item.product_id,
        qty: item.quantity,
        unit: 'cases'
      }))
    }, {
      headers: {
        'Authorization': `Bearer ${props.user.token}`
      }
    })

    cartItems.value = []
    localStorage.removeItem('cartItems')
    cartOpen.value = false
    currentTab.value = 'orders'
    showToast('Order created successfully!', 'success')
    await fetchOrders()
  } catch (err) {
    showToast('Failed to create order', 'error')
    console.error(err)
  }
}

const openAccountSettings = () => {
  settingsOpen.value = true
  accountOpen.value = false
}

const saveSettings = async () => {
  try {
    await axios.put(`${import.meta.env.VITE_API_URL}/api/account`, {
      company_name: props.user.company_name,
      email: props.user.email
    })
    settingsOpen.value = false
    showToast('Settings saved', 'success')
  } catch (err) {
    showToast('Failed to save settings', 'error')
  }
}

const handleLogout = () => {
  emit('logout')
}

const showToast = (message, type = 'info') => {
  toast.value = { show: true, message, type }
  setTimeout(() => {
    toast.value.show = false
  }, 3000)
}

const formatDate = (date) => {
  return new Date(date).toLocaleDateString()
}

const formatPrice = (price) => {
  return `$${parseFloat(price).toFixed(2)}`
}

// Configure axios with auth header
const setupAuth = () => {
  if (props.user && props.user.token) {
    axios.defaults.headers.common['Authorization'] = `Bearer ${props.user.token}`
  }
}

// Lifecycle
onMounted(() => {
  setupAuth()
  
  // Load from localStorage
  const stored = localStorage.getItem('cartItems')
  if (stored) {
    try {
      cartItems.value = JSON.parse(stored)
    } catch (e) {}
  }

  const storedFav = localStorage.getItem('favorites')
  if (storedFav) {
    try {
      favorites.value = JSON.parse(storedFav)
    } catch (e) {}
  }

  // Fetch from API
  fetchProducts()
  fetchOrders()
})
</script>

