<template>
  <aside class="sidebar" :class="{ 'open-mobile': sidebarOpen }">
    <div class="sb-top">
      <div class="sb-label">Categories</div>
    </div>
    <div class="sb-search">
      <input
        v-model="searchTerm"
        type="text"
        placeholder="Search…"
        @input="filterCategories"
      />
    </div>

    <div
      class="sb-all"
      :class="{ active: activeFilter === 'all' }"
      @click="selectFilter('all', null)"
    >
      <span style="font-size: 14px">📦</span> All Products
      <span class="a-count">{{ totalCount }}</span>
    </div>

    <div class="sb-divider"></div>

    <div v-for="cat in filteredCategories" :key="cat.id" class="sb-super-btn"
         :class="{ active: activeFilter === cat.id }"
         @click="selectFilter('category', cat.id)"
    >
      <span class="s-emoji">{{ cat.emoji || '📁' }}</span>
      <span class="s-label">{{ cat.name }}</span>
      <span class="s-cnt">{{ cat.count }}</span>
    </div>

    <div class="sb-divider"></div>

    <div class="sb-special" @click="selectFilter('special', 'favorites')">
      ❤️ Favorites <span style="margin-left: auto; font-size: 10px; background: var(--bg); padding: 1px 6px; border-radius: 20px; border: 1px solid var(--border)">{{ favCount }}</span>
    </div>
  </aside>
</template>

<script setup>
import { ref, computed, watch } from 'vue'

const props = defineProps({
  categories: {
    type: Array,
    default: () => []
  },
  activeFilter: {
    type: [String, Number],
    default: 'all'
  },
  favorites: {
    type: Array,
    default: () => []
  },
  products: {
    type: Array,
    default: () => []
  },
  sidebarOpen: {
    type: Boolean,
    default: false
  }
})

const emit = defineEmits(['filter-change'])

const searchTerm = ref('')

const filteredCategories = computed(() => {
  if (!searchTerm.value) return props.categories
  const term = searchTerm.value.toLowerCase()
  return props.categories.filter(cat => cat.name.toLowerCase().includes(term))
})

const totalCount = computed(() => props.products.length)

const favCount = computed(() => props.favorites.length)

const selectFilter = (type, value) => {
  emit('filter-change', { type, value })
}

const filterCategories = () => {
  // Categories are filtered via computed property
}
</script>

