<template>
  <div class="cart-drawer" :class="{ open: isOpen }">
    <div class="cart-header">
      <h2>Shopping Cart</h2>
      <button class="btn-close" @click="$emit('close')">✕</button>
    </div>

    <div class="cart-body">
      <div v-if="items.length === 0" class="cart-empty">
        <div class="empty-icon">🛒</div>
        <div>Your cart is empty</div>
      </div>

      <div v-else class="cart-items">
        <div v-for="item in items" :key="item.product_id" class="cart-item">
          <img
            v-if="item.image_url"
            :src="item.image_url"
            :alt="item.name"
            class="item-image"
          />
          <div class="item-info">
            <div class="item-name">{{ item.name }}</div>
            <div class="item-price">{{ formatPrice(item.price) }}</div>
          </div>
          <div class="item-controls">
            <button class="qty-btn" @click="updateQuantity(item.product_id, item.quantity - 1)">−</button>
            <span class="qty-display">{{ item.quantity }}</span>
            <button class="qty-btn" @click="updateQuantity(item.product_id, item.quantity + 1)">+</button>
          </div>
          <button class="btn-remove" @click="removeFromCart(item.product_id)">🗑</button>
        </div>
      </div>
    </div>

    <div v-if="items.length > 0" class="cart-footer">
      <div class="cart-total">
        <span>Total:</span>
        <span class="total-price">{{ formatPrice(totalPrice) }}</span>
      </div>
      <button class="btn-checkout" @click="checkout">Proceed to Checkout</button>
      <button class="btn-clear" @click="clearCart">Clear Cart</button>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'

const props = defineProps({
  items: {
    type: Array,
    default: () => []
  },
  isOpen: {
    type: Boolean,
    default: false
  }
})

const emit = defineEmits(['close', 'update-quantity', 'remove-item', 'checkout', 'clear-cart'])

const totalPrice = computed(() => {
  return props.items.reduce((sum, item) => sum + (item.price * item.quantity), 0)
})

const formatPrice = (price) => {
  return `$${parseFloat(price).toFixed(2)}`
}

const updateQuantity = (productId, newQty) => {
  if (newQty > 0) {
    emit('update-quantity', { productId, quantity: newQty })
  }
}

const removeFromCart = (productId) => {
  emit('remove-item', productId)
}

const clearCart = () => {
  emit('clear-cart')
}

const checkout = () => {
  emit('checkout')
}
</script>

