<template>
  <div class="login-container">
    <div class="login-card">
      <div class="login-header">
        <div class="brand-logo">🔥</div>
        <div class="brand-name"><span>DR</span> Prepper</div>
        <div class="brand-subtitle">Wholesale Portal</div>
      </div>

      <!-- Mode Tabs -->
      <div class="mode-tabs">
        <button
          :class="['mode-tab', { active: mode === 'signin' }]"
          @click="mode = 'signin'"
        >
          Sign In
        </button>
        <button
          :class="['mode-tab', { active: mode === 'create' }]"
          @click="mode = 'create'"
        >
          Create Account
        </button>
      </div>

      <!-- Sign In Form -->
      <form v-if="mode === 'signin'" @submit.prevent="handleLogin" class="login-form">
        <div class="form-group">
          <label for="email">Email Address</label>
          <input
            id="email"
            v-model="email"
            type="email"
            placeholder="buyer@company.com"
            required
            :disabled="loading"
          />
        </div>

        <div class="form-group">
          <label for="password">Password</label>
          <input
            id="password"
            v-model="password"
            type="password"
            placeholder="Enter password"
            required
            :disabled="loading"
          />
        </div>

        <button type="submit" class="btn-login" :disabled="loading">
          {{ loading ? 'Signing in...' : 'Sign In' }}
        </button>

        <div v-if="error" class="error-message">
          {{ error }}
        </div>
      </form>

      <!-- Create Account Form -->
      <form v-if="mode === 'create'" @submit.prevent="handleCreateAccount" class="login-form">
        <div class="form-group">
          <label for="company">Company Name</label>
          <input
            id="company"
            v-model="newAccount.company"
            type="text"
            placeholder="e.g. Happy Snacks Co."
            required
            :disabled="loading"
          />
        </div>

        <div class="form-group">
          <label for="name">Your Name</label>
          <input
            id="name"
            v-model="newAccount.name"
            type="text"
            placeholder="First and last name"
            required
            :disabled="loading"
          />
        </div>

        <div class="form-group">
          <label for="create-email">Email Address</label>
          <input
            id="create-email"
            v-model="newAccount.email"
            type="email"
            placeholder="you@company.com"
            required
            :disabled="loading"
          />
        </div>

        <div class="form-group">
          <label for="create-password">Password</label>
          <input
            id="create-password"
            v-model="newAccount.password"
            type="password"
            placeholder="At least 8 characters"
            required
            :disabled="loading"
            @input="updatePasswordStrength"
          />
          <!-- Password Strength Indicator -->
          <div class="password-strength">
            <div class="strength-bar">
              <div
                class="strength-fill"
                :class="`strength-${passwordStrength.level}`"
                :style="{ width: passwordStrength.percentage + '%' }"
              ></div>
            </div>
            <span class="strength-text" :class="`strength-${passwordStrength.level}`">
              {{ passwordStrength.text }}
            </span>
          </div>
          <!-- Requirements -->
          <div class="password-requirements">
            <div :class="['requirement', { met: passwordChecks.length8 }]">
              ✓ At least 8 characters
            </div>
            <div :class="['requirement', { met: passwordChecks.hasUppercase }]">
              ✓ One uppercase letter
            </div>
            <div :class="['requirement', { met: passwordChecks.hasLowercase }]">
              ✓ One lowercase letter
            </div>
            <div :class="['requirement', { met: passwordChecks.hasNumber }]">
              ✓ One number
            </div>
          </div>
        </div>

        <div class="form-group">
          <label for="confirm-password">Confirm Password</label>
          <input
            id="confirm-password"
            v-model="newAccount.confirmPassword"
            type="password"
            placeholder="Repeat password"
            required
            :disabled="loading"
          />
          <div v-if="newAccount.password && newAccount.confirmPassword && newAccount.password !== newAccount.confirmPassword" class="error-text">
            Passwords do not match
          </div>
        </div>

        <button
          type="submit"
          class="btn-login"
          :disabled="loading || !isCreateFormValid"
        >
          {{ loading ? 'Creating account...' : 'Request Access' }}
        </button>

        <div v-if="error" class="error-message">
          {{ error }}
        </div>
        <div v-if="success" class="success-message">
          {{ success }}
        </div>
      </form>

      <div class="demo-creds">
        <div class="demo-title">Demo Credentials</div>
        <div class="demo-row">
          <strong>Buyer:</strong> buyer@happysnacks.com / demo1234
        </div>
        <div class="demo-row">
          <strong>Admin:</strong> admin@drprepper.com / admin123
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import axios from 'axios'

const emit = defineEmits(['login'])

const mode = ref('signin')
const email = ref('')
const password = ref('')
const loading = ref(false)
const error = ref('')
const success = ref('')

const newAccount = ref({
  company: '',
  name: '',
  email: '',
  password: '',
  confirmPassword: ''
})

const passwordChecks = ref({
  length8: false,
  hasUppercase: false,
  hasLowercase: false,
  hasNumber: false
})

const passwordStrength = ref({
  level: 'weak',
  text: 'Weak',
  percentage: 0
})

const isCreateFormValid = computed(() => {
  return (
    newAccount.value.company &&
    newAccount.value.name &&
    newAccount.value.email &&
    newAccount.value.password &&
    newAccount.value.confirmPassword &&
    newAccount.value.password === newAccount.value.confirmPassword &&
    passwordChecks.value.length8 &&
    passwordChecks.value.hasUppercase &&
    passwordChecks.value.hasLowercase &&
    passwordChecks.value.hasNumber
  )
})

const updatePasswordStrength = () => {
  const pwd = newAccount.value.password
  
  // Check individual requirements
  passwordChecks.value.length8 = pwd.length >= 8
  passwordChecks.value.hasUppercase = /[A-Z]/.test(pwd)
  passwordChecks.value.hasLowercase = /[a-z]/.test(pwd)
  passwordChecks.value.hasNumber = /\d/.test(pwd)
  
  // Calculate strength
  let strength = 0
  if (passwordChecks.value.length8) strength++
  if (passwordChecks.value.hasUppercase) strength++
  if (passwordChecks.value.hasLowercase) strength++
  if (passwordChecks.value.hasNumber) strength++
  
  const strengthLevels = ['weak', 'fair', 'good', 'strong']
  const strengthTexts = ['Weak', 'Fair', 'Good', 'Strong']
  const strengthPercentages = [25, 50, 75, 100]
  
  const index = Math.max(0, strength - 1)
  passwordStrength.value.level = strengthLevels[index]
  passwordStrength.value.text = strengthTexts[index]
  passwordStrength.value.percentage = strengthPercentages[index]
}

const handleLogin = async () => {
  error.value = ''
  success.value = ''
  loading.value = true

  try {
    const response = await axios.post(`${import.meta.env.VITE_API_URL}/api/auth/login`, {
      email: email.value,
      password: password.value
    })

    const { token, vendor } = response.data
    
    // Determine role based on email
    const role = email.value === 'admin@drprepper.com' ? 'admin' : 'customer'
    
    emit('login', {
      id: vendor.id,
      email: vendor.email,
      contact_name: vendor.name,
      company_name: vendor.companyName,
      role,
      token
    })
  } catch (err) {
    error.value = err.response?.data?.error || 'Login failed. Please try again.'
  } finally {
    loading.value = false
  }
}

const handleCreateAccount = async () => {
  error.value = ''
  success.value = ''
  
  if (!isCreateFormValid.value) {
    error.value = 'Please fill in all fields with a strong password.'
    return
  }

  loading.value = true

  try {
    // In a real app, this would POST to /api/auth/register
    // For now, show a success message
    success.value = 'Account request submitted! The DR Prepper team will review and email you once approved.'
    
    // Reset form
    setTimeout(() => {
      mode.value = 'signin'
      newAccount.value = {
        company: '',
        name: '',
        email: '',
        password: '',
        confirmPassword: ''
      }
      success.value = ''
    }, 2000)
  } catch (err) {
    error.value = err.response?.data?.error || 'Failed to create account. Please try again.'
  } finally {
    loading.value = false
  }
}
</script>

