<script setup>
import { ref, computed, onMounted } from 'vue'
import axios from 'axios'

const props = defineProps({
  user: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['logout'])

// State
const products = ref([])
const orders = ref([])
const customers = ref([])

// UI State
const currentTab = ref('catalog')
const sidebarOpen = ref(false)
const catalogSearch = ref('')
const orderFilter = ref('all')
const toast = ref({ show: false, message: '', type: 'info' })

// Modals
const showAddProductModal = ref(false)
const showAddCustomerModal = ref(false)

const newProduct = ref({
  name: '',
  sku: '',
  price: 0,
  category: '',
  image_url: '',
  visible: true
})

const newCustomer = ref({
  company_name: '',
  email: '',
  password: ''
})

// Computed
const filteredProducts = computed(() => {
  if (!catalogSearch.value) return products.value
  const q = catalogSearch.value.toLowerCase()
  return products.value.filter(p =>
    p.name.toLowerCase().includes(q) ||
    p.sku.toLowerCase().includes(q)
  )
})

const filteredOrders = computed(() => {
  if (orderFilter.value === 'all') return orders.value
  return orders.value.filter(o => o.status === orderFilter.value)
})

// Methods
const fetchProducts = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/products`)
    products.value = response.data
  } catch (err) {
    showToast('Failed to load products', 'error')
  }
}

const fetchOrders = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/admin/orders`)
    orders.value = response.data
  } catch (err) {
    showToast('Failed to load orders', 'error')
  }
}

const fetchCustomers = async () => {
  try {
    const response = await axios.get(`${import.meta.env.VITE_API_URL}/api/admin/customers`)
    customers.value = response.data
  } catch (err) {
    showToast('Failed to load customers', 'error')
  }
}

const saveProduct = async () => {
  try {
    if (newProduct.value.id) {
      await axios.put(`${import.meta.env.VITE_API_URL}/api/products/${newProduct.value.id}`, newProduct.value)
    } else {
      await axios.post(`${import.meta.env.VITE_API_URL}/api/products`, newProduct.value)
    }
    showAddProductModal.value = false
    newProduct.value = { name: '', sku: '', price: 0, category: '', image_url: '', visible: true }
    showToast('Product saved', 'success')
    await fetchProducts()
  } catch (err) {
    showToast('Failed to save product', 'error')
  }
}

const editProduct = (product) => {
  newProduct.value = { ...product }
  showAddProductModal.value = true
}

const deleteProduct = async (id) => {
  if (!confirm('Delete this product?')) return
  try {
    await axios.delete(`${import.meta.env.VITE_API_URL}/api/products/${id}`)
    showToast('Product deleted', 'success')
    await fetchProducts()
  } catch (err) {
    showToast('Failed to delete product', 'error')
  }
}

const toggleProductVisibility = async (id) => {
  const product = products.value.find(p => p.id === id)
  if (product) {
    try {
      await axios.patch(`${import.meta.env.VITE_API_URL}/api/products/${id}`, {
        visible: !product.visible
      })
      product.visible = !product.visible
      showToast('Product updated', 'success')
    } catch (err) {
      showToast('Failed to update product', 'error')
    }
  }
}

const openAddProductModal = () => {
  newProduct.value = { name: '', sku: '', price: 0, category: '', image_url: '', visible: true }
  showAddProductModal.value = true
}

const saveCustomer = async () => {
  try {
    await axios.post(`${import.meta.env.VITE_API_URL}/api/admin/customers`, newCustomer.value)
    showAddCustomerModal.value = false
    newCustomer.value = { company_name: '', email: '', password: '' }
    showToast('Customer added', 'success')
    await fetchCustomers()
  } catch (err) {
    showToast('Failed to add customer', 'error')
  }
}

const editCustomer = (customer) => {
  // Implement edit modal
}

const deleteCustomer = async (id) => {
  if (!confirm('Delete this customer?')) return
  try {
    await axios.delete(`${import.meta.env.VITE_API_URL}/api/admin/customers/${id}`)
    showToast('Customer deleted', 'success')
    await fetchCustomers()
  } catch (err) {
    showToast('Failed to delete customer', 'error')
  }
}

const customerOrders = (customerId) => {
  return orders.value.filter(o => o.customer_id === customerId)
}

const updateOrderStatus = async (orderId, status) => {
  try {
    await axios.patch(`${import.meta.env.VITE_API_URL}/api/admin/orders/${orderId}`, { status })
    const order = orders.value.find(o => o.id === orderId)
    if (order) order.status = status
    showToast('Order updated', 'success')
  } catch (err) {
    showToast('Failed to update order', 'error')
  }
}

const viewOrder = (order) => {
  alert(JSON.stringify(order, null, 2))
}

const toggleSidebar = () => {
  sidebarOpen.value = !sidebarOpen.value
}

const openAddCustomerModal = () => {
  newCustomer.value = { company_name: '', email: '', password: '' }
  showAddCustomerModal.value = true
}

const handleLogout = () => {
  emit('logout')
}

const showToast = (message, type = 'info') => {
  toast.value = { show: true, message, type }
  setTimeout(() => {
    toast.value.show = false
  }, 3000)
}

const formatDate = (date) => {
  return new Date(date).toLocaleDateString()
}

// Lifecycle
onMounted(() => {
  fetchProducts()
  fetchOrders()
  fetchCustomers()
})
</script>

