<template>
  <div id="app">
    <Login v-if="!currentUser" @login="handleLogin" />
    <template v-else>
      <CustomerPortal v-if="currentUser.role === 'customer'" @logout="handleLogout" :user="currentUser" />
      <AdminPortal v-else-if="currentUser.role === 'admin'" @logout="handleLogout" :user="currentUser" />
    </template>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import Login from './components/Login.vue'
import CustomerPortal from './components/CustomerPortal.vue'
import AdminPortal from './components/AdminPortal.vue'

const currentUser = ref(null)

const handleLogin = (user) => {
  currentUser.value = user
  localStorage.setItem('currentUser', JSON.stringify(user))
  localStorage.setItem('authToken', user.token)
}

const handleLogout = () => {
  currentUser.value = null
  localStorage.removeItem('currentUser')
  localStorage.removeItem('authToken')
}

onMounted(() => {
  const stored = localStorage.getItem('currentUser')
  if (stored) {
    try {
      currentUser.value = JSON.parse(stored)
    } catch (e) {
      localStorage.removeItem('currentUser')
    }
  }
})
</script>

